        raw_part_json = source.raw_part_json
WHEN NOT MATCHED THEN
    INSERT (
        run_uuid,
        part_number,
        item_number,
        description,
        quantity,
        page_roles,
        pages,
        materials,
        surface_finishes,
        colours,
        revisions,
        drawing_numbers,
        thicknesses_mm,
        dimensions_mm,
        angles_deg,
        hole_sizes_mm,
        slot_sizes_mm,
        process_notes,
        operations,
        manufacturing_features,
        manufacturing_interpretation,
        geometry_rollup,
        part_json,
        raw_part_json
    )
    VALUES (
        source.run_uuid,
        source.part_number,
        source.item_number,
        source.description,
        source.quantity,
        source.page_roles,
        source.pages,
        source.materials,
        source.surface_finishes,
        source.colours,
        source.revisions,
        source.drawing_numbers,
        source.thicknesses_mm,
        source.dimensions_mm,
        source.angles_deg,
        source.hole_sizes_mm,
        source.slot_sizes_mm,
        source.process_notes,
        source.operations,
        source.manufacturing_features,
        source.manufacturing_interpretation,
        source.geometry_rollup,
        source.part_json,
        source.raw_part_json
    );

COMMIT TRANSACTION;
